from research_helpers import source, assessment, record, scope, evidence, decision, write_batch

refs=[
 ('earth2150','Earth 2150 review','Tim Soete, GameSpot','https://www.gamespot.com/reviews/earth-2150-review/1900-2591131/','UCS has an entirely robotic workforce/army; the Lunar Corporation is a separate advanced lunar faction.','UCS provision cannot be silently assigned to the queued Lunar Corporation. The strong UCS lead is saved for later queue expansion.'),
 ('ctp1','Factory in Civilization: Call to Power','Game Great Library, transcribed by Civilization Wiki','https://civilization.fandom.com/wiki/Factory_%28CTP1%29','The first game’s factory uses laborers to increase production.','An earlier technology is not proof of the late nanite economy; the second game’s Nanite Factory was not imported into the first.'),
 ('saat','S.A.A.T.','Anno 2070 Wiki contributors','https://anno2070.fandom.com/wiki/S.A.A.T.','AI coordination, scientists, production chains and a research council define the faction.','Human-machine symbiosis and advanced science do not establish ordinary household provision independent of labor.'),
 ('offworld','Offworld Trading Company official description','Mohawk Games / Stardock on Steam','https://store.steampowered.com/app/271240/','Corporations compete to supply the colonized planet through markets.','The human colony’s ordinary rights/work arrangements are not described; a robotic HQ’s needs cannot stand for all human consumers.'),
 ('offworld-robots','Offworld Trading Company founders change log','Stardock / Yarlen','https://www.stardock.com/games/article/460883/offworld-trading-company-v004397-change-log','The early official rules distinguish Robotic HQ consumption from other firms.','Historical pre-release patch only, not a current human household constitution or proof all production workers are robots.'),
 ('mars-service','Service Bots developer clarification','Haemimont developer Mnementh on Steam','https://steamcommunity.com/app/464920/discussions/0/2949168687321268517/','The marked developer reply confirms that upgraded service buildings operate without personnel.','Original game, 2018 clarification; medical/security jobs are not assumed eliminated and no exact performance balance is adopted.'),
 ('mars-farm','Fully automated farms discussion','Surviving Mars Steam contributors','https://steamcommunity.com/app/464920/discussions/0/4521040918052910872/','Green Planet’s Open Farm requires no human workers, with environmental/crop prerequisites.','Historical original-game configuration, not the changed Relaunched farming system; normal Automated Farming does not itself remove every worker.'),
 ('mars-residents','Housing, jobs and food discussion','Surviving Mars Steam contributors','https://steamcommunity.com/app/464920/discussions/0/3087760096577984055/','Housing, stocked services, food access and jobs are separately managed; unemployed residents remain part of the colony.','Player explanation, not a legal welfare charter; adequate housing and accessible supply are explicit conditions, and mods are not used.'),
 ('frost-laws','Frostpunk 2 laws','Game Vault wiki contributors transcribing law/event text','https://frostpunk-2.game-vault.net/wiki/Law','Free Essentials can remain unconditional; Paid Essentials can deny aid; Machine Attendants replaces production labor with machinery plus maintenance.','Qualitative law configurations only, not a claim to current numerical balancing. Workforce reductions and event percentages are not population nonworking rates.'),
 ('ixion-work','IXION prologue','Ixion Wiki contributors','https://ixion.fandom.com/wiki/Prologue','Workers, farms, quarters, EVA construction and human responsibility remain part of Tiqqun operations.','An advisor AI does not alone determine productive control or replace essential human work.'),
 ('ixion-remus','IXION plot and endings','Wikipedia contributors','https://en.wikipedia.org/wiki/Ixion_(video_game)','Ashtangites on Remus are bioengineered human descendants who offer conditional settlement; EDDEN conceals an alternative planet.','Remus is not a machine welfare society merely because people are biologically adapted; no settled post-ending allocation is supplied.'),
 ('startopia','Startopia gameplay','Wikipedia contributors','https://en.wikipedia.org/wiki/Startopia','Droids clean/build/repair, while hired alien employees operate facilities and visitors spend money.','The original game is distinct from Spacebase Startopia; commercial guests and employees are not all supplied nonworkers.'),
 ('spacebase','Spacebase Startopia launch information','Steam launch post quoting publisher copy','https://steamcommunity.com/app/840390/discussions/0/3080998989605715556/','Fuzzies perform menial tasks while the Commander manages visitors, residents, berths, food and medical facilities.','Release-description context only; assistance from VAL is not proof of an independently governed welfare floor.'),
 ('eve-crew','Ship crew','CCP Games, EVE Universe','https://universe.eveonline.com/lore/ship-crew','Capsuleer ships usually have crews; engineers, quartermasters and dock workers perform essential labor.','Official lore replaces player-fiction crew primers; rare uncrewed ships are not treated as the ordinary whole economy.'),
 ('elite-codex','Knowledge Base codex','Elite Dangerous game codex, transcribed by Elite Dangerous Wiki','https://elite-dangerous.fandom.com/wiki/Knowledge_Base','The interstellar ban on self-aware AI constrains Achilles robotics; human governments and corporate interests vary.','Only the relevant ban/governance entries; Guardian history is a different species and forum robot role-play is not canon.')
]
S=[source('src-b83-'+sid,title,author,url,'official_or_labeled_rules_reference','Short bounded public/indexed description or rules passage',claim,limits) for sid,title,author,url,claim,limits in refs]
m=['src-b83-mars-service','src-b83-mars-farm','src-b83-mars-residents'];f=['src-b83-frost-laws']
R=[record('surviving-mars-automated-human-colony','c0693','Surviving Mars — Human colony with automated food and services','Surviving Mars','A modeled inhabited colony using Open Farms and Service Bots',['game'],
 scope('Original Surviving Mars with Green Planet; historically documented configuration','A supplied, housed colony after Open Farm prerequisites and Service Bots upgrades','Living human colonists in the configured settlement',['Biorobots silently treated as uploaded humans','A wholly uninhabited drone-only terraforming run','Medical and security work assumed abolished','Relaunched’s changed food systems'],player_configurable=True,branch='Inhabited Green Planet colony with automated food production and upgraded services'),
 'Open Farms can supply food without human farm workers, while Service Bots remove staff requirements from many ordinary service buildings. In this inhabited configuration, housing and accessible stocks support human colonists while machines replace substantial subsistence and domestic labor. It is a partial post-work colony rather than a claim of complete automation: medicine, security, research, manufacturing and maintenance can still require people. Adequate housing, environmental conditions and functioning logistics are explicit parts of the setup.\n\nHuman administration chooses buildings, upgrades and resource priorities, so control is placed near concentrated human direction rather than an independent AI government. The game’s command interface does not establish that every resident jointly owns the productive assets. Guarantees are moderately strong within the supplied settlement, but broad uncertainty remains because food routing, shortages and administrative decisions can interrupt provision. Colonists are not automatically nonworkers merely because some services need no staff; useful research, care and creative activity still count. The participation axis remains unresolved, and artificial biorobots are not silently added to the human denominator.',
 {'guarantees':-0.5,'control':0.1,'nonworking':None},
 {'guarantees':assessment(-0.5,[-0.85,0.35],'low','Automated food/services and separately managed housing support residents, but logistics, stocks and administration remain important conditions.',m),
  'control':assessment(0.1,[0,0.4],'low','Human colony administration directs production/upgrades; neither robot operation nor the interface establishes autonomous AI or equal ownership.',m),
  'nonworking':assessment(None,None,'low','Automation removes selected staff requirements, not all useful colonist activity; no all-person census is given.',m)},
 1,m,[evidence('An actual allowed configuration combines zero-human-worker Open Farm production with personnel-free upgraded services.',m,'Original-game developer Service Bots clarification and Green Planet Open Farm discussion','developer_clarification_and_labeled_gameplay_reference')],
 ['Explicit original-game configuration; no imported Relaunched changes or mods.', 'Partial automation with continuing useful human work.', 'Housing, environmental prerequisites and accessible food logistics are conditions.', 'Biorobot personhood/origin is not assumed.'])]

for suffix,name,free,g,interval in [
 ('free-essentials','unconditional Free Essentials',True,-0.65,[-0.9,0.2]),
 ('paid-no-allowance','Paid Essentials without an unemployment allowance',False,0.85,[0.55,1])
]:
    description=(
      'This modeled New London combines machine-centered production with an explicit distribution choice. Under Free Essentials, the city supplies basic rations and clothing without payment, and the selected follow-up keeps provision independent of a work requirement. Machinery reduces the need for direct production labor, while human maintenance and other useful tasks remain. The arrangement therefore weakens the link between employment and necessities without pretending that the whole city has stopped working. The guarantee estimate is strong but conditional on available supplies and survival through the cold.\n\nThe Steward and council organize the rules and resource system. That supports concentrated human institutional control, with uncertainty about the wider ownership of machinery; votes on laws do not establish equal productive ownership. People who leave the formal workforce may still perform care or other useful activity. Neither the law’s workforce modifier nor an automaton’s nominal labor equivalent supplies an all-person nonworking percentage, so that axis stays unresolved. The paid-essentials alternative is recorded separately because it materially changes access to the same mechanized output.'
      if free else
      'This modeled New London uses the same machine-centered production approach but charges citizens for basic rations and clothing. When unemployed families cannot afford these necessities, the selected event choice declines an allowance. Automation can reduce demand for direct human production work without giving displaced people a secure claim on its output. The weak-guarantee score therefore reflects an implemented access rule and its explicit hardship consequence, rather than merely the city’s dangerous weather or an assumption that every resident is poor.\n\nThe human Steward and council shape economic rules; machines do not thereby become an autonomous government. Human maintenance and other useful work continues, and the record makes no claim that all formal jobs are unnecessary. Workforce reductions, unused labor capacity and automaton equivalents are different from an all-age participation census, so nonworking remains null. This is an explicit player-selected partial-transition configuration, not every Frostpunk 2 city or a fixed canonical ending. Its material difference from the free variant is the decision to leave unemployed residents without guaranteed essentials.'
    )
    R.append(record('frostpunk2-automation-'+suffix,'c0694','Frostpunk 2 — Automation with '+name,'Frostpunk 2','Mechanized New London under '+name,['game'],
      scope('Frostpunk 2 law/event model','Established configured city under '+name,'Living human citizens of the configured New London',['The alternative necessities law as the same access system','Machine workforce units counted as humans','Nominal workforce as an all-age nonworking census','The original Frostpunk’s different automaton rules'],player_configurable=True,branch='Machine Attendants with emergency shutdowns and '+name),
      description,{'guarantees':g,'control':0.1,'nonworking':None},
      {'guarantees':assessment(g,interval,'medium','Free provision remains independent of work, subject to supply.' if free else 'Payment remains necessary and the chosen response denies unemployed families an allowance.',f),
       'control':assessment(0.1,[0,0.45],'low','Human Steward/council rules govern production/access; equal ownership and independent AI authority are not established.',f),
       'nonworking':assessment(None,None,'low','Machine substitution and formal workforce changes do not census useful activity by all humans.',f)},
      1 if free else 3,f,[evidence('Machine Attendants reduces direct production labor while the selected necessities law changes access independently.',f,'New Work Model / Machine Attendants and Basic Necessities law/event text','transcribed_game_rules_and_event_choices')],
      ['A modeled, explicitly chosen legal/economic configuration.', 'Continuing human maintenance and other useful work remains visible.', 'Availability and environmental survival constrain guarantees.', 'No workforce percentage is treated as a population participation statistic.']))

rows=[
 ('c0689','needs_evidence',['earth2150'],'The Lunar Corporation’s advanced technology does not establish its household allocation.','The clear all-robot workforce description belongs to the separate UCS faction, saved as a later discovery lead rather than silently substituted.'),
 ('c0690','needs_evidence',['ctp1'],'The first Call to Power’s late nanite-era material constitution remains unverified.','Ordinary factory labor is explicit, but a second-game Nanite Factory cannot establish the first game’s later household distribution.'),
 ('c0691','needs_evidence',['saat'],'S.A.A.T. science and AI coordination do not establish a general work-independent material floor.','Researchers and efficient production chains remain useful human activity; scientific governance is not the missing allocation mechanism.'),
 ('c0692','needs_evidence',['offworld','offworld-robots'],'Robotic firms and corporate supply markets do not establish ordinary human colonists’ work-independent access.','A robotic HQ’s needs differ from human consumers; mods offering fully automated sponsor colonies were discarded.'),
 ('c0695','needs_evidence',['ixion-work'],'Tiqqun’s AI advice and construction drones do not establish replacement of its essential human production work.','Workers, quarters and farms have real requirements; the label non-worker is not an all-person absence of useful activity.'),
 ('c0696','needs_evidence',['ixion-remus'],'Remus’s bioengineered Ashtangites do not have a verified technological material-allocation system in the short account.','Biological adaptation, a settlement offer and EDDEN’s preferences do not supply the colony’s ordinary resource constitution.'),
 ('c0697','boundary_case',['startopia'],'The original station hires useful alien staff and sells services to visitors despite droid assistance.','Commercial hospitality, cleaning/construction robots and temporary tourists do not establish a durable work-independent resident floor.'),
 ('c0698','needs_evidence',['spacebase'],'VAL and Fuzzy assistance do not establish a complete work-independent population economy.','The station’s visitor/resident services still need actual access and productive-labor rules; the 2001 original is not imported.'),
 ('c0699','boundary_case',['eve-crew'],'Capsuleer technology does not remove the actual engineers, quartermasters and dock workers sustaining ships.','Official lore explicitly retains crews; immortality and personal wealth are not a whole industrial post-work system.'),
 ('c0700','needs_evidence',['elite-codex'],'The self-aware-AI ban is real, but its relation to a qualifying general labor/subsistence arrangement remains unresolved.','A robotics constraint across heterogeneous governments is not enough to assign one welfare/control point or prove a deliberate employment-preserving order.')
]
D=[decision(cid,status,reason,['src-b83-'+s for s in ss],analysis=analysis,follow_up='Keep the short disposition and continue; do not rescue unclear settings through full manuals or role-playing extrapolation.') for cid,status,ss,reason,analysis in rows]
D.append(decision('c0693','included','A documented inhabited model combines automatic farming and personnel-free services with ordinary human resident support.',m,society_id=R[0]['id']))
D.append(decision('c0694','included','Two allowed law/event configurations materially change access to mechanized output.',f,society_id=R[1]['id'],society_ids=[R[1]['id'],R[2]['id']],split_rationale='Unconditional Free Essentials and Paid Essentials with an explicitly refused allowance implement opposing material access rules for comparable mechanized cities; these are labeled alternative player configurations, not two simultaneous canonical cities.'))
D.sort(key=lambda x:x['candidate_id'])
write_batch(83,[f'c{i:04}' for i in range(689,701)],S,R,D,[
 'Twelve ordered candidate decisions yield three records through one explicit distribution-policy split.',
 'Original Surviving Mars / Green Planet is kept separate from Relaunched and mods. Service automation does not abolish medicine, security or all human work.',
 'Frostpunk 2’s free versus paid essentials materially differ despite the same automation policy. Exact workforce modifiers are not converted into population nonworking.',
 'UCS was discovered while checking Lunar Corporation and is saved for later stable-ID expansion; it is not substituted into the wrong candidate.',
 'Official EVE crew lore replaces player fiction. Anno/Offworld mods, Elite role-play and a Call to Power sequel mismatch were discarded.'
])
